        // source: plugin/PrintJobHistory/js/PrintJobHistory-PluginCheckDialog.js
        
        
        function PrintJobHistoryPluginCheckDialog(){
        
            var self = this;
        
            self.apiClient = null;
            myPluginSettings = null;
        
            self.missingPluginsDialog = null;
            self.missingPluginMessage = null;
            self.confirmButton = null;
            self.deactivatePluginCheck = ko.observable(false);
        
            self.init = function(apiClient, pluginSettings){
                self.apiClient = apiClient;
                myPluginSettings = pluginSettings
                self.missingPluginsDialog = $("#dialog_printJobHistory_missingPlugins");
                self.missingPluginMessage = $("#missingPluginMessage");
                self.confirmButton = $("button.btn-confirm", self.missingPluginsDialog);
            }
        
            this.isInitialized = function() {
                return self.apiClient != null;
            }
        
            this.hideDialog = function(){
                self.missingPluginsDialog.modal('hide');
            }
        
            this.showMissingPluginsDialog = function(dialogMessage){
                if (self.missingPluginsDialog != null && self.missingPluginsDialog.is(":visible")){
                    return;
                }
        
                self.missingPluginMessage.html(dialogMessage);
        
                self.confirmButton.unbind("click");
                self.confirmButton.bind("click", function() {
                    disableCheck = self.deactivatePluginCheck();
                    if (disableCheck == true) {
                        myPluginSettings.pluginCheckActivated(false)
                        self.apiClient.callDeactivatePluginCheck();
                    }
                    self.hideDialog();
                });
        
                self.missingPluginsDialog.modal({
                    //minHeight: function() { return Math.max($.fn.modal.defaults.maxHeight() - 80, 250); }
                    keyboard: false,
                    clickClose: false,
                    showClose: false,
                    backdrop: "static"
                }).css({
                    width: 'auto',
                    'margin-left': function() { return -($(this).width() /2); }
                });
            }
        
        
        
        }
        
        ;
        
        // source: plugin/PrintJobHistory/js/PrintJobHistory-MessageConfirmDialog.js
        
        
        function PrintJobHistoryPluginMessageConfirmDialog(){
        
            var self = this;
        
            self.apiClient = null;
            myPluginSettings = null;
        
            self.messageConfirmDialog = null;
            self.confirmMessage = null;
            self.confirmButton = null;
        
            self.init = function(apiClient, pluginSettings){
                self.apiClient = apiClient;
                myPluginSettings = pluginSettings
                self.messageConfirmDialog = $("#dialog_printJobHistory_messageConfirm");
                self.confirmMessage = $("#confirmMessage", self.messageConfirmDialog);
                self.confirmButton = $("#pjh_confirmmessage_button", self.messageConfirmDialog);
                self.cancelButton = $("#pjh_cancel_button", self.messageConfirmDialog);
            }
        
            this.isInitialized = function() {
                return self.apiClient != null;
            }
        
            this.hideDialog = function(){
                self.messageConfirmDialog.modal('hide');
            }
        
            this.showDialog = function(messageConfirmData){
                if (self.messageConfirmDialog != null && self.messageConfirmDialog.is(":visible")){
                    return;
                }
        
                //
                var dialogMessage = "<h1>" + messageConfirmData.title + "</h1>" +
                                    "<span>" + messageConfirmData.data + "</span>";
        
                self.confirmMessage.html(dialogMessage);
        
                self.confirmButton.unbind("click");
                self.confirmButton.bind("click", function() {
                    self.apiClient.callConfirmMessageDialog();
                    self.hideDialog();
                });
        
                self.cancelButton.unbind("click");
                self.cancelButton.bind("click", function() {
                    self.hideDialog();
                });
        
                self.messageConfirmDialog.modal({
                    //minHeight: function() { return Math.max($.fn.modal.defaults.maxHeight() - 80, 250); }
                    keyboard: false,
                    clickClose: false,
                    showClose: false,
                    backdrop: "static"
                }).css({
                    width: 'auto',
                    'margin-left': function() { return -($(this).width() /2); }
                });
            }
        
        
        
        }
        
