                self.showPopup = function(message_type, title, text){
                    if (self.popup !== undefined){
                        self.closePopup();
                    }
                    self.popup = new PNotify({
                        title: gettext(title),
                        text: text,
                        type: message_type,
                        hide: false
                    });
                };
        
